  position: relative; display: inline-flex; align-items: center; gap: var(--space-xs);
  min-height: var(--control-h); padding: var(--space-xs) var(--space-md);
  border: var(--rule-hair) solid var(--color-rule-2); border-radius: var(--radius-input);
  background: var(--color-key-face); color: var(--color-ink); box-shadow: var(--shadow-key);
  font-size: var(--text-sm); line-height: 1.45; text-align: left; cursor: pointer;
  transition: transform var(--dur-micro) var(--ease-out), box-shadow var(--dur-micro) var(--ease-out), background-color var(--dur-micro) var(--ease-out), border-color var(--dur-micro) var(--ease-out);
}
.chip input { position: absolute; width: 1px; height: 1px; margin: 0; opacity: 0; pointer-events: none; }
.chip__check { width: 14px; height: 14px; opacity: 0; color: var(--color-accent-text); }
@media (hover: hover) { .chip:hover { background: var(--color-key-hover); border-color: var(--color-muted); } }
