}
::selection { background: color-mix(in oklab, var(--color-accent) 24%, transparent); color: var(--color-ink); }
:focus-visible { outline: 2px solid var(--color-focus); outline-offset: 2px; }
a { color: inherit; text-decoration-thickness: 1px; text-underline-offset: 0.18em; }
h1, h2, h3, h4 { margin: 0; font-family: var(--font-display); font-weight: 600; font-synthesis: none; letter-spacing: -0.012em; line-height: 1.3; overflow-wrap: break-word; min-width: 0; color: var(--color-ink); }
h1 { font-size: var(--text-2xl); } h2 { font-size: var(--text-xl); } h3 { font-size: var(--text-lg); } h4 { font-size: var(--text-md); }
p { margin: 0; text-wrap: pretty; }
ul, ol { margin: 0; }
img, video { max-width: 100%; height: auto; display: block; }
svg { flex: none; }
[hidden] { display: none !important; }
button, input, select, textarea { font: inherit; color: inherit; }
code, kbd, pre, .mono { font-family: var(--font-mono); }
.num { font-variant-numeric: tabular-nums; }
.visually-hidden { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

/* ---------- app shell ---------- */
.app-shell { min-height: 100dvh; display: grid; grid-template-rows: auto minmax(0, 1fr); }
.app-main { width: 100%; max-width: var(--container); margin-inline: auto; padding: var(--space-lg) var(--gutter) var(--space-2xl); }
.app-main--full { max-width: none; padding: 0; }
.page-head { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: var(--space-md); margin-bottom: var(--space-lg); }
.page-head__text { display: grid; gap: var(--space-2xs); min-width: 0; }
.page-head__desc { color: var(--color-ink-2); max-width: 60ch; }

.app-header {
  position: sticky; top: 0; z-index: var(--z-sticky-nav);
  display: flex; align-items: center; gap: var(--space-lg);
  height: var(--header-h); padding-inline: var(--gutter);
  background: var(--color-paper); border-bottom: var(--rule-hair) solid var(--color-rule);
}
.app-brand { display: inline-flex; align-items: center; gap: var(--space-xs); border-radius: var(--radius-input); color: var(--color-ink); font-weight: 700; font-size: var(--text-md); line-height: 1; letter-spacing: -0.01em; text-decoration: none; white-space: nowrap; }
.app-brand img { width: 28px; height: 28px; }
